    function updateEdges(){document.querySelectorAll('.edge-group').forEach(group=>{const source=stateBounds(group.dataset.source),target=stateBounds(group.dataset.target);if(!source||!target)return;const {x1,y1,x2,y2}=connectionPoints(source,target);const bend=Math.max(35,Math.min(100,Math.hypot(x2-x1,y2-y1)*0.25));const horizontal=Math.abs(x2-x1)>=Math.abs(y2-y1);const d=horizontal?'M '+x1+' '+y1+' C '+(x1+(x2>=x1?bend:-bend))+' '+y1+', '+(x2+(x2>=x1?-bend:bend))+' '+y2+', '+x2+' '+y2:'M '+x1+' '+y1+' C '+x1+' '+(y1+(y2>=y1?bend:-bend))+', '+x2+' '+(y2+(y2>=y1?-bend:bend))+', '+x2+' '+y2;group.querySelectorAll('path').forEach(path=>path.setAttribute('d',d));const label=group.querySelector('text'),labelX=(x1+x2)/2,labelY=(y1+y2)/2-8;label.setAttribute('x',String(labelX));label.setAttribute('y',String(labelY));const hit=group.querySelector('.transition-label-hit'),labelWidth=Math.max(80,label.textContent.length*7+20);hit.setAttribute('x',String(labelX-labelWidth/2));hit.setAttribute('y',String(labelY-18));hit.setAttribute('width',String(labelWidth));hit.setAttribute('height','28');});}
